<?php
namespace App\Services;
use Illuminate\Support\Facades\Http;
class SearchConsole {
 public function sync():array {$p=Settings::providers()['analytics']??[];abort_unless(!empty($p['searchConsoleProperty'])&&!empty($p['searchConsoleServiceAccount']),422,'Add Search Console credentials and property first.');$a=json_decode($p['searchConsoleServiceAccount'],true,64,JSON_THROW_ON_ERROR);$enc=fn($v)=>rtrim(strtr(base64_encode($v),'+/','-_'),'=');$jwt=$enc(json_encode(['alg'=>'RS256','typ'=>'JWT'])).'.'.$enc(json_encode(['iss'=>$a['client_email'],'scope'=>'https://www.googleapis.com/auth/webmasters.readonly','aud'=>'https://oauth2.googleapis.com/token','iat'=>time(),'exp'=>time()+3600]));abort_unless(openssl_sign($jwt,$signature,$a['private_key'],OPENSSL_ALGO_SHA256),422);$token=Http::asForm()->timeout(15)->post('https://oauth2.googleapis.com/token',['grant_type'=>'urn:ietf:params:oauth:grant-type:jwt-bearer','assertion'=>$jwt.'.'.$enc($signature)])->throw()->json('access_token');$result=['source'=>'Google Search Console API','startDate'=>now()->subDays(31)->toDateString(),'endDate'=>now()->subDays(3)->toDateString(),'updatedAt'=>now()->toIso8601String()];foreach(['query','page'] as $dim){$d=Http::withToken($token)->timeout(20)->post('https://www.googleapis.com/webmasters/v3/sites/'.rawurlencode($p['searchConsoleProperty']).'/searchAnalytics/query',['startDate'=>$result['startDate'],'endDate'=>$result['endDate'],'dimensions'=>[$dim],'rowLimit'=>5000])->throw()->json();$result[$dim]=array_map(fn($r)=>['key'=>$r['keys'][0],'clicks'=>$r['clicks'],'impressions'=>$r['impressions'],'ctr'=>$r['ctr'],'position'=>$r['position']],$d['rows']??[]);}Settings::put('searchData',$result);return $result;}
}
